/*
 * storage.js — SAFE BROWSER STORAGE
 * The only file that touches the browser's localStorage. If storage is
 * blocked (for example in private mode) it falls back to memory so the site
 * never crashes. Do not edit this file.
 */

/*
 * SECTION 1 — STORAGE SETTINGS
 * A backup place in memory, and a prefix added to every saved name so
 * this site does not clash with other sites.
 */
const memoryStorage = {};

const STORAGE_PREFIX = "lpuHub_";

/*
 * SECTION 2 — SAVE, LOAD, REMOVE AND CLEAR
 * storageSave stores a value, storageLoad reads it (or gives a default),
 * storageRemove deletes one value and storageClearAll deletes everything of this site.
 */
function storageSave(name, value) {
  const fullKey = STORAGE_PREFIX + name;
  try {
    const serialized = JSON.stringify(value);
    memoryStorage[fullKey] = serialized;
    window.localStorage.setItem(fullKey, serialized);
  } catch (error) {
    memoryStorage[fullKey] = JSON.stringify(value);
  }
}

function storageLoad(name, fallback) {
  const fullKey = STORAGE_PREFIX + name;
  try {
    const raw = window.localStorage.getItem(fullKey);
    if (raw !== null) {
      return JSON.parse(raw);
    }
  } catch (error) {
  }
  if (memoryStorage.hasOwnProperty(fullKey)) {
    try {
      return JSON.parse(memoryStorage[fullKey]);
    } catch (e) {
      return fallback;
    }
  }
  return fallback;
}

function storageRemove(name) {
  const fullKey = STORAGE_PREFIX + name;
  try {
    delete memoryStorage[fullKey];
    window.localStorage.removeItem(fullKey);
  } catch (error) {
    delete memoryStorage[fullKey];
  }
}

function storageClearAll() {
  try {
    const keysToRemove = [];
    for (let i = 0; i < window.localStorage.length; i++) {
      const key = window.localStorage.key(i);
      if (key && key.indexOf(STORAGE_PREFIX) === 0) {
        keysToRemove.push(key);
      }
    }
    for (let j = 0; j < keysToRemove.length; j++) {
      window.localStorage.removeItem(keysToRemove[j]);
      delete memoryStorage[keysToRemove[j]];
    }
  } catch (error) {
    for (const k in memoryStorage) {
      delete memoryStorage[k];
    }
  }
}
